from copy import deepcopy


def prepare_examples(records, holdout_stride):
    """Validate records and build independent deterministic data partitions."""
    if isinstance(holdout_stride, bool) or not isinstance(holdout_stride, int) or holdout_stride < 2:
        raise ValueError("holdout_stride must be an integer of at least 2")

    result = {
        "sector": {"train": [], "validation": []},
        "distance": {"train": [], "validation": []},
    }
    for position, record in enumerate(records, 1):
        if not isinstance(record, dict) or set(record) != {"pixels", "sector", "distance"}:
            raise TypeError("each record must have exactly the required keys")
        if not isinstance(record["sector"], str) or not record["sector"]:
            raise ValueError("sector must be a non-empty string")
        if not isinstance(record["distance"], str) or not record["distance"]:
            raise ValueError("distance must be a non-empty string")

        pixels = record["pixels"]
        if isinstance(pixels, (str, bytes)) or not pixels:
            raise ValueError("pixels must be a non-empty matrix")
        width = None
        for row in pixels:
            if isinstance(row, (str, bytes)) or not row:
                raise ValueError("pixel rows must be non-empty")
            if width is None:
                width = len(row)
            elif len(row) != width:
                raise ValueError("pixels must be rectangular")
            for value in row:
                if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= 255:
                    raise ValueError("pixel values must be integers from 0 to 255")

        bucket = "validation" if position % holdout_stride == 0 else "train"
        for target in ("sector", "distance"):
            result[target][bucket].append({
                "pixels": deepcopy(pixels),
                "label": record[target],
            })
    return result
